INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Spark Salons @ Unlikely Collaborators in Santa Monica', 'New York Los Angeles Mingle', 'Women in Business', 'Hi all! There is a great non profit space in Santa Monica called Unlikely Collaborators that hosts a monthly event with a speaker called', 'Hi all! There is a great non profit space in Santa Monica called Unlikely Collaborators that hosts a monthly event with a speaker called Spark Salons. I have attended several of the events and enjoy them. They are free to attend though you must RSVP on their website (see below for their Eventbrite links) and they also offer some complimentary food and drinks which is nice. There are three more events this year if you want to rsvp and check them out - sometimes events do get full so please rsvp More info: https://www.meetup.com/new-yorkers-in-los-angeles/events/316904067/', '2026-12-01T17:00:00-08:00', 'Unlikely Collaborators', '1520 2nd Street', 'Santa Monica', 'CA', '', 34.03, -118.49, 'New York Los Angeles Mingle', 17, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/new-yorkers-in-los-angeles/events/316904067/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('The Venice Fest Holiday Market', 'New York Los Angeles Mingle', 'Women in Business', 'Hi all! I went to the winter Venice Fest last year and it was a lot of fun! It was packed and there were lots of booths to check out plus I', 'Hi all! I went to the winter Venice Fest last year and it was a lot of fun! It was packed and there were lots of booths to check out plus I went to the Taverna at The Mar Vista which had a DJ. I will probably pick for us to meet at the bar area of the Taverna and then we can walk around. I don''t know what time I want to go yet and will decide later - maybe it will be around 2pm. The festival is from 11am to 6pm. [https://www.thevenicefest.com/](https://www.thevenicefest.com/) More info: https://www.meetup.com/new-yorkers-in-los-angeles/events/316568772/', '2026-12-05T14:30:00-08:00', 'TAVERNA at The Mar Vista', '12249 Venice Blvd., Los Angeles, CA 90066, USA', 'Los Angeles', 'CA', '90066', 34.004733266823, -118.431916296434, 'New York Los Angeles Mingle', 57, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/new-yorkers-in-los-angeles/events/316568772/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
