INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('October Happy Hour - NextGen Orlando!', 'NextGen Orlando - A Professional Networking Group', 'Young Professionals', 'We’re bringing NextGen to the **House on Lang** where art, creativity, and connection come together in the heart of Mills 50 District.', 'We’re bringing NextGen to the **House on Lang** where art, creativity, and connection come together in the heart of Mills 50 District. We’re also proud to support our non-profit of the month, the **Doglando Foundation,** which has developed and designed programs that provide a safe, nurturing, and enrichment-filled environment for pregnant rescue dogs and their puppies to grow, socialize, explore and thrive. **Event Details:** Place: House on Lang \| 1308 Lang Ave Date: Monday, October 12th More info: https://www.meetup.com/nextgen-orlando-a-professional-networking-group/events/316595650/', '2026-10-12T17:30:00-04:00', 'The House on Lang', '1308 Lang Ave, Orlando, FL 32803, USA', 'Orlando', 'FL', '32803', 28.562241153908, -81.365134233545, 'NextGen Orlando - A Professional Networking Group', 99, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/nextgen-orlando-a-professional-networking-group/events/316595650/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('October Volunteer Event - NextGen Orlando!', 'NextGen Orlando - A Professional Networking Group', 'Young Professionals', '**🐶Volunteer with Next Gen Orlando at Doglando Foundation!🐶** Volunteers will be assembling puppy enrichment activities that volunteers and', '**🐶Volunteer with Next Gen Orlando at Doglando Foundation!🐶** Volunteers will be assembling puppy enrichment activities that volunteers and fosters can check out to play with the puppies and dogs in Doglando Foundation''s care. Doglando Foundation will have some options as to how we can help. That way you can do what is most meaningful to you and choose how involved you would like to get. Everyone will get a chance to play with the puppies and parents they have. They will have a few different More info: https://www.meetup.com/nextgen-orlando-a-professional-networking-group/events/316915489/', '2026-10-15T17:30:00-04:00', '12276 East Colonial Drive', '12276 E Colonial Dr, Orlando, FL 32826, USA', 'Orlando', 'FL', '32826', 28.56567727997, -81.19830293526, 'NextGen Orlando - A Professional Networking Group', 10, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/nextgen-orlando-a-professional-networking-group/events/316915489/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('The Data Behind Agents: Building Intelligent, Safe, AI Systems', 'North Seattle Tech Talks', 'Founders & Startups', '**WHAT IS IT ABOUT?** AI agents dominate current industry discussion, yet clear explanations of **what they are, why they fail, and what', '**WHAT IS IT ABOUT?** AI agents dominate current industry discussion, yet clear explanations of **what they are, why they fail, and what roles they are creating remain scarce**. This session offers a foundational introduction for students and early-career technologists. We''ll examine what distinguishes an agent from a conventional chatbot — tools, memory, and planning loops — and trace an agent through the completion of a realistic task. We then turn to the less-demonstrated half of the More info: https://www.meetup.com/north-seattle-tech-talks/events/315764530/', '2026-11-09T17:30:00-08:00', 'Online event', 'Online event', 'Seattle', 'WA', '', 47.67, -122.34, 'North Seattle Tech Talks', 39, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/north-seattle-tech-talks/events/315764530/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('NVPPA Photographers - Board Meeting - We Need Committee Chairs - Volunteer!', 'NVPPA: Northern Virginia Professional Photographers | VA DC', 'General Networking', 'RSVP Required. We''d like to add you to our management team. We are a highly motivated, enthusiastic, and smart-working team. Please let us', 'RSVP Required. We''d like to add you to our management team. We are a highly motivated, enthusiastic, and smart-working team. Please let us know if you''re qualified... Please read and understand the Member''s Promise (https://www.meetup.com/Northern-Virginia-Professional-Photographers-VA-DC/about/). We are a volunteer organization so members are only entitled to what each board member and committee member donates of their time, dedication, and enthusiastic attention. We need committee chairs / More info: https://www.meetup.com/northern-virginia-professional-photographers-va-dc/events/316686830/', '2026-10-13T19:30:00-04:00', 'Panera - Woodbridge', '2804 Prince William Pkwy', 'Woodbridge', 'VA', '', 38.68, -77.31, 'NVPPA: Northern Virginia Professional Photographers | VA DC', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/northern-virginia-professional-photographers-va-dc/events/316686830/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
